+using Microsoft.ML;
+using TicketClassifier.Models;
+
+namespace TicketClassifier.Services;
+
+public sealed class ModelTrainingService
+{
+    private readonly ILogger<ModelTrainingService> _logger;
+
+    public ModelTrainingService(ILogger<ModelTrainingService> logger)
+    {
+        _logger = logger;
+    }
+
+    public string TrainAndSave(string dataPath, string modelPath)
+    {
+        var mlContext = new MLContext(seed: 42);
+
+        IDataView data = mlContext.Data.LoadFromTextFile<TicketInput>(
+            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
+
+        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
+
+        var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject))
+            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
+            .Append(mlContext.Transforms.Concatenate("Features",
+                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
+            .Append(mlContext.Transforms.NormalizeMinMax("Features"))
+            .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
+            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
+                labelColumnName: "Label", featureColumnName: "Features"))
+            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
+
+        _logger.LogInformation("Training model with {TrainCount} training rows...",
+            mlContext.Data.CreateEnumerable<TicketInput>(split.TrainSet, reuseRowObject: false).Count());
+
+        var model = pipeline.Fit(split.TrainSet);
+
+        // Evaluate on test set
+        var predictions = model.Transform(split.TestSet);
+        var metrics = mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");
+
+        var report = FormatMetrics(metrics);
+        _logger.LogInformation("Model evaluation on test set:\n{Metrics}", report);
+
+        // Retrain on full dataset for production model
+        var productionModel = pipeline.Fit(data);
+        mlContext.Model.Save(productionModel, data.Schema, modelPath);
+        _logger.LogInformation("Model saved to {Path}", modelPath);
+
+        return report;
+    }
+
+    private static string FormatMetrics(
+        Microsoft.ML.Data.MulticlassClassificationMetrics metrics)
+    {
+        return $"""
+            ╔══════════════════════════════════════════╗
+            ║     Multiclass Classification Metrics    ║
+            ╠══════════════════════════════════════════╣
+            ║  Macro Accuracy:   {metrics.MacroAccuracy,20:P2} ║
+            ║  Micro Accuracy:   {metrics.MicroAccuracy,20:P2} ║
+            ║  Log Loss:         {metrics.LogLoss,20:F4} ║
+            ║  Log Loss Reduction:{metrics.LogLossReduction,19:F4} ║
+            ╚══════════════════════════════════════════╝
+            Per-class log-loss: {string.Join(", ", metrics.PerClassLogLoss.Select((v, i) => $"Class {i}: {v:F4}"))}
+            Confusion Matrix:
+            {metrics.ConfusionMatrix.GetFormattedConfusionTable()}
+            """;
+    }
+}
+

